#include <stdint.h>

#include "stm32f411xe.h"
#include "stm32f4xx.h"

#define LED_OK_PIN              GPIO_ODR_OD1
#define TIM11_PRESCALER_VALUE    15999U
#define TIM11_AUTO_RELOAD_VALUE  499U

volatile uint8_t bandera_tim11 = 0U;

static void led_ok_Init(void);
static void tim11_Init(void);

int main(void)
{
	led_ok_Init();
	tim11_Init();

	while (1)
	{
		if (bandera_tim11 == 1U)
		{
			bandera_tim11 = 0U;

			if ((GPIOH->ODR & LED_OK_PIN) != 0U)
			{
				GPIOH->BSRR = GPIO_BSRR_BR1;
			}
			else
			{
				GPIOH->BSRR = GPIO_BSRR_BS1;
			}
		}
	}
}

static void led_ok_Init(void)
{
	/* Habilitar GPIOH y configurar PH1 (LED2 de expansion) como salida. */
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOHEN;
	GPIOH->MODER &= ~GPIO_MODER_MODE1;
	GPIOH->MODER |= GPIO_MODER_MODE1_0;

	/* Iniciar LED_OK apagado. */
	GPIOH->BSRR = GPIO_BSRR_BR1;
}

static void tim11_Init(void)
{
	/* TIM11 genera un evento cada 500 ms con reloj de 16 MHz. */
	RCC->APB2ENR |= RCC_APB2ENR_TIM11EN;
	TIM11->PSC = TIM11_PRESCALER_VALUE;
	TIM11->ARR = TIM11_AUTO_RELOAD_VALUE;
	TIM11->CNT = 0U;

	/* TIM11 comparte su vector de interrupcion con TIM1. */
	TIM11->DIER |= TIM_DIER_UIE;
	NVIC_EnableIRQ(TIM1_TRG_COM_TIM11_IRQn);
	__enable_irq();

	/* CEN se activa al final de la configuracion. */
	TIM11->CR1 |= TIM_CR1_CEN;
}

void TIM1_TRG_COM_TIM11_IRQHandler(void)
{
	if ((TIM11->SR & TIM_SR_UIF) != 0U)
	{
		TIM11->SR &= ~TIM_SR_UIF;
		bandera_tim11 = 1U;
	}
}